}

return [{ 
  stock_keys: stockArr,
  stock_keys_str: stockStr 
}];

smaArr = [];
for (const item of $input.first().json.data) {
  if (item.window_padding == 1) continue;
  calculatedItem = {
    trade_date: item.trade_date,
    symbol: item.stock_key,
    sma_20: item.sum_close_20 / 20,
    sma_50: item.sum_close_50 / 50,
    sma_100: item.sum_close_100 / 100
  }
  smaArr.push(calculatedItem)
}

return smaArr;

