data = $input.first().json.data;

// Distribute raw data rows into groups by stock_key
grouped = {};
for (const item of data) {
  if (!grouped[item.stock_key]) grouped[item.stock_key] = [];
  grouped[item.stock_key].push(item);
}

periods = [7, 14, 21];
rsiArr = [];

for (const symbol in grouped) {
  rows = grouped[symbol].sort((a, b) => new Date(a.trade_date) - new Date(b.trade_date));

  state = {};
  for (const p of periods) {
    state[p] = { ag: null, al: null, sumGain: 0, sumLoss: 0 };
  }

  rows.forEach((item, i) => {
    rowsSeen = i + 1;
    calculatedItem = {
      trade_date: item.trade_date,
      symbol: symbol
    };

    for (const p of periods) {
      state[p].sumGain += item.gain;
      state[p].sumLoss += item.loss;

      if (rowsSeen < p) {
        calculatedItem['rsi_' + p] = null;
        continue;
      }

      if (rowsSeen === p) {
        // Seed: initial average gain/loss over the first n periods
        state[p].ag = state[p].sumGain / p;
        state[p].al = state[p].sumLoss / p;
      } else {
        // Wilder's smoothing recursion
        state[p].ag = (state[p].ag * (p - 1) + item.gain) / p;
        state[p].al = (state[p].al * (p - 1) + item.loss) / p;
      }

      ag = state[p].ag;
      al = state[p].al;
      calculatedItem['rsi_' + p] = al === 0 ? (ag === 0 ? 50 : 100) : 100 - (100 / (1 + (ag / al)));
    }
    if (item.window_padding != 1) rsiArr.push(calculatedItem);
  });
}

return rsiArr;

