function getPercentile(arr, percentile) {
  if (arr.length === 0) return 0;
  if (arr.length === 1) return arr[0];

  const sorted = [...arr].sort((a, b) => a - b);
  const index = (sorted.length - 1) * percentile;
  const lower = Math.floor(index);
  const upper = Math.ceil(index);
  const weight = index - lower;

  if (upper >= sorted.length) return sorted[sorted.length - 1];
  return sorted[lower] * (1 - weight) + sorted[upper] * weight;
}

const windowSize = 20;

// Extract rows array from ClickHouse JSON wrapper ($input.first().json.data)
const inputData = $input.first()?.json?.data || [];

// Group items by stock_key
const groupedData = {};
for (const item of inputData) {
  const stock = item.stock_key;
  if (!groupedData[stock]) {
    groupedData[stock] = [];
  }
  groupedData[stock].push(item);
}

const outputItems = [];

// Process each stock group
for (const stock in groupedData) {
  const stockItems = groupedData[stock].sort(
    (a, b) => new Date(a.trade_date) - new Date(b.trade_date)
  );

  for (let i = 0; i < stockItems.length; i++) {
    const currentItem = stockItems[i];

    if (Number(currentItem.window_padding) === 0) {
      const startIndex = Math.max(0, i - windowSize + 1);
      const windowVolumes = stockItems
        .slice(startIndex, i + 1)
        .map((d) => parseFloat(d.volume) || 0);

      const p25 = getPercentile(windowVolumes, 0.25);
      const p75 = getPercentile(windowVolumes, 0.75);
      const iqr = p75 - p25;

      outputItems.push({
        json: {
          trade_date: currentItem.trade_date,
          symbol: currentItem.stock_key,
          volume_iqr_p25: Number(p25.toFixed(4)),
          volume_iqr_p75: Number(p75.toFixed(4)),
          volume_rolling_iqr: Number(iqr.toFixed(4))
        }
      });
    }
  }
}

return outputItems;

/**
 * Helper: Calculates the Arithmetic Mean
 */
function getMean(arr) {
  if (arr.length === 0) return 0;
  const sum = arr.reduce((acc, val) => acc + val, 0);
  return sum / arr.length;
}

/**
 * Helper: Calculates the Sample Standard Deviation
 */
function getSampleStdDev(arr) {
  if (arr.length <= 1) return 0;
  const mean = getMean(arr);
  const variance = arr.reduce((acc, val) => acc + Math.pow(val - mean, 2), 0) / (arr.length - 1);
  return Math.sqrt(variance);
}

const windowSize = 20;

// Extract rows array from ClickHouse JSON response ($input.first().json.data)
const inputData = $input.first()?.json?.data || [];

// Group items by stock symbol (stock_key)
const groupedData = {};
for (const item of inputData) {
  const stock = item.stock_key;
  if (!groupedData[stock]) {
    groupedData[stock] = [];
  }
  groupedData[stock].push(item);
}

const outputItems = [];

// Process each stock series
for (const stock in groupedData) {
  // Sort time series in ascending order
  const stockItems = groupedData[stock].sort(
    (a, b) => new Date(a.trade_date) - new Date(b.trade_date)
  );

  // STEP 1: Compute log_return_t2 for each trade session: log(close_t / close_{t-2})
  const series = stockItems.map((item, index) => {
    const closeCurr = parseFloat(item.close) || 0;

    let logReturnT2 = 0;
    if (index >= 2) {
      const closeLag2 = parseFloat(stockItems[index - 2].close) || 0;
      if (closeLag2 > 0 && closeCurr > 0) {
        logReturnT2 = Math.log(closeCurr / closeLag2);
      }
    }

    return {
      trade_date: item.trade_date,
      symbol: item.stock_key,
      close_price: closeCurr,
      log_return_t2: logReturnT2,
      window_padding: item.window_padding
    };
  });

  // STEP 2: Compute metrics STRICTLY when window_padding === 0
  for (let i = 0; i < series.length; i++) {
    const curr = series[i];

    // Evaluate ONLY when window_padding is strictly 0
    if (Number(curr.window_padding) === 0) {
      // 20-period rolling window slice (ROWS BETWEEN 19 PRECEDING AND CURRENT ROW)
      const startIndex = Math.max(0, i - windowSize + 1);
      const windowSlice = series.slice(startIndex, i + 1);
      const windowReturns = windowSlice.map((d) => d.log_return_t2);

      const expectedReturn = getMean(windowReturns);
      const volatility = getSampleStdDev(windowReturns);

      // Map output fields directly to n8n_olap.fact_portfolio_return_metrics schema
      outputItems.push({
        json: {
          symbol: curr.symbol,
          trade_date: curr.trade_date,
          close_price: Number(curr.close_price.toFixed(4)),
          log_return_t2: Number(curr.log_return_t2.toFixed(6)),
          expected_return_t2_n20: Number(expectedReturn.toFixed(6)),
          volatility_t2_n20: Number(volatility.toFixed(6))
        }
      });
    }
  }
}

return outputItems;

